package com.citacloud.springboot.contacloud.app.views.components;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.errors.UiErrorHandler;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.services.ValeCajaService;
import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.data.value.ValueChangeMode;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.function.Consumer;

public class ValesCajaDialog extends Dialog {
 private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");private final UUID sesionId;private final ValeCajaService service;private final Consumer<UUID> imprimir;private final boolean puedeCrear,puedeImprimir,puedeAnular;private final ValeCajaContextoDto contexto;private final TextField buscar=new TextField("Buscar");private final Select<EstadoValeCaja> estado=new Select<>();private final AppGrid<ValeCajaDto> grid=new AppGrid<>(ValeCajaDto.class);private final AppPagination paginacion;
 public ValesCajaDialog(UUID sesion,ValeCajaService service,Consumer<UUID> imprimir,boolean crear,boolean print,boolean anular){sesionId=Objects.requireNonNull(sesion);this.service=Objects.requireNonNull(service);this.imprimir=imprimir;puedeCrear=crear;puedeImprimir=print;puedeAnular=anular;contexto=service.contexto(sesion);setHeaderTitle("VALES DE CAJA");setWidth("min(1180px, 96vw)");setMaxHeight("92vh");configurar();paginacion=new AppPagination(r->cargar(),5,5,10,20,50);Div encabezado=new Div(new H3(contexto.caja()+" · "+contexto.sucursal()),new Span(contexto.abierta()?"● Abierta":"● Cerrada"));encabezado.addClassName("cc-cash-movement-heading");Div filtros=new Div(buscar,estado);filtros.addClassNames("cc-filter-bar","cc-cash-voucher-filters");VerticalLayout contenido=new VerticalLayout(encabezado,filtros,grid,paginacion);contenido.setPadding(false);contenido.setSpacing(false);add(contenido);if(crear)getFooter().add(new AppActionButton(ActionType.NEW,ButtonSize.MAIN,"Nuevo vale",e->nuevo()));getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->close()));cargar();}
 private void configurar(){buscar.setPlaceholder("Número, beneficiario, concepto o referencia...");buscar.setClearButtonVisible(true);buscar.setValueChangeMode(ValueChangeMode.LAZY);buscar.setValueChangeTimeout(350);estado.setLabel("Estado");estado.setItems(EstadoValeCaja.values());estado.setEmptySelectionAllowed(true);estado.setEmptySelectionCaption("Todos");estado.setItemLabelGenerator(ValesCajaDialog::estado);buscar.addValueChangeListener(e->{if(e.isFromClient())reiniciar();});estado.addValueChangeListener(e->{if(e.isFromClient())reiniciar();});grid.addColumn(ValeCajaDto::numero).setHeader("Número").setAutoWidth(true);grid.addColumn(x->fecha(x.fechaHora())).setHeader("Fecha/Hora").setAutoWidth(true);grid.addColumn(ValeCajaDto::beneficiario).setHeader("Beneficiario").setFlexGrow(1);grid.addColumn(ValeCajaDto::concepto).setHeader("Concepto").setFlexGrow(1);grid.addColumn(x->x.monedaCodigo()+" "+PosNumberFormatter.money(x.importe())).setHeader("Importe").setAutoWidth(true).setTextAlign(com.vaadin.flow.component.grid.ColumnTextAlign.END);grid.addComponentColumn(x->{Span s=new Span(estado(x.estado()));s.getElement().getThemeList().add("badge "+(x.estado()==EstadoValeCaja.CONFIRMED?"success":"error"));return s;}).setHeader("Estado").setAutoWidth(true);grid.addComponentColumn(x->new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver vale",e->ver(x.id()))).setHeader("Acc.").setAutoWidth(true).setFlexGrow(0);grid.setEmptyStateText("No se encontraron vales de caja.");}
 private void cargar(){try{var r=paginacion.currentRequest();var p=service.buscarPos(sesionId,buscar.getValue(),estado.getValue(),r.page(),r.size());grid.setItems(p.getContent());paginacion.setTotal(p.getTotalElements());}catch(RuntimeException ex){grid.setItems(List.of());paginacion.setTotal(0);UiErrorHandler.show(ex,"No fue posible consultar los vales de caja.");}}
 private void reiniciar(){paginacion.reset();cargar();}
 private void nuevo(){ValeCajaContextoDto actual=service.contexto(sesionId);if(!actual.abierta()){UiErrorHandler.show(new IllegalStateException(),"La caja debe estar abierta para confirmar un vale.");return;}Dialog d=new Dialog();d.setHeaderTitle("NUEVO VALE DE CAJA");d.setWidth("min(680px, 96vw)");TextField fecha=new TextField("Fecha/Hora");fecha.setValue(DT.format(LocalDateTime.now()));fecha.setReadOnly(true);TextField moneda=new TextField("Moneda");moneda.setValue(actual.monedaCodigo());moneda.setReadOnly(true);ComboBox<ConceptoValeCajaDto> concepto=new ComboBox<>("Concepto");concepto.setItems(actual.conceptos());concepto.setItemLabelGenerator(ConceptoValeCajaDto::nombre);concepto.setRequiredIndicatorVisible(true);TextField beneficiario=new TextField("Beneficiario");beneficiario.setRequiredIndicatorVisible(true);beneficiario.setMaxLength(180);BigDecimalField importe=new BigDecimalField("Importe");importe.setRequiredIndicatorVisible(true);importe.setPrefixComponent(new Span(actual.monedaCodigo()));TextField referencia=new TextField("Referencia");referencia.setMaxLength(100);TextArea observacion=new TextArea("Observación");observacion.setMaxLength(500);PosNumericKeypad teclado=new PosNumericKeypad(PosNumericKeypad.Mode.POPOVER);var boton=teclado.bind(importe,d,PosNumericKeypad.Options.money(()->{}),v->{});HorizontalLayout monto=new HorizontalLayout(importe,boton);monto.setWidthFull();monto.setAlignItems(FlexComponent.Alignment.END);monto.expand(importe);concepto.addValueChangeListener(e->{ConceptoValeCajaDto c=e.getValue();referencia.setRequiredIndicatorVisible(c!=null&&c.requiereReferencia());observacion.setRequiredIndicatorVisible(c!=null&&c.requiereObservacion());});Div form=new Div(fecha,moneda,concepto,beneficiario,monto,referencia,observacion,teclado);form.addClassNames("cc-dialog-form","cc-cash-voucher-form");d.add(form);UUID clave=UUID.randomUUID();AppActionButton confirmar=new AppActionButton(ActionType.ACCEPT,ButtonSize.MAIN,"Confirmar vale",null);confirmar.addClickListener(e->{confirmar.setEnabled(false);try{ValeCajaDto creado=service.confirmar(new ValeCajaInput(sesionId,concepto.getValue()==null?null:concepto.getValue().id(),importe.getValue(),beneficiario.getValue(),referencia.getValue(),observacion.getValue(),clave));d.close();reiniciar();com.vaadin.flow.component.notification.Notification.show("Vale de caja confirmado correctamente.");ver(creado.id());}catch(RuntimeException ex){confirmar.setEnabled(true);UiErrorHandler.show(ex,"No fue posible confirmar el vale de caja.");}});d.getFooter().add(confirmar,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->{teclado.close();d.close();}));d.open();}
 private void ver(UUID id){try{ValeCajaDto v=service.obtener(id);Dialog d=new Dialog();d.setHeaderTitle("VER VALE DE CAJA");d.setWidth("min(760px, 96vw)");AppDetailSection info=new AppDetailSection("Información").field("Número",v.numero()).field("Estado",estado(v.estado())).field("Fecha/Hora",fecha(v.fechaHora())).field("Caja",v.caja()).field("Sucursal",v.sucursal()).field("Usuario",v.usuario()).field("Beneficiario",v.beneficiario()).field("Concepto",v.concepto()).field("Referencia",v.referencia()==null?"—":v.referencia()).field("Importe",v.monedaCodigo()+" "+PosNumberFormatter.money(v.importe())).field("Observación",v.observacion()==null?"—":v.observacion());if(v.estado()==EstadoValeCaja.VOIDED)info.field("Anulado por",v.usuarioAnulacion()).field("Fecha anulación",fecha(v.anuladoEn())).field("Motivo",v.motivoAnulacion());d.add(info);if(puedeImprimir)d.getFooter().add(new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Reimprimir vale",e->imprimir.accept(v.id())));if(puedeAnular&&v.anulable())d.getFooter().add(new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Anular",e->anular(d,v)));d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}catch(RuntimeException ex){UiErrorHandler.show(ex,"No fue posible consultar el vale de caja.");}}
 private void anular(Dialog detalle,ValeCajaDto v){Dialog d=new Dialog();d.setHeaderTitle("ANULAR VALE DE CAJA");TextArea motivo=new TextArea("Motivo de anulación");motivo.setRequiredIndicatorVisible(true);motivo.setMaxLength(500);motivo.setWidthFull();d.add(new Paragraph("Se registrará una entrada de efectivo inversa. El vale original permanecerá en el historial."),motivo);UUID clave=UUID.randomUUID();AppActionButton confirmar=new AppActionButton(ActionType.VOID,ButtonSize.MAIN,"Anular vale",null);confirmar.addClickListener(e->{confirmar.setEnabled(false);try{service.anular(new AnulacionValeCajaInput(v.id(),motivo.getValue(),clave));d.close();detalle.close();reiniciar();com.vaadin.flow.component.notification.Notification.show("Vale de caja anulado correctamente.");}catch(RuntimeException ex){confirmar.setEnabled(true);UiErrorHandler.show(ex,"No fue posible anular el vale de caja.");}});d.getFooter().add(confirmar,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->d.close()));d.open();}
 private static String fecha(OffsetDateTime v){return v==null?"—":DT.format(v.atZoneSameInstant(ZoneId.systemDefault()));}private static String estado(EstadoValeCaja e){return e==EstadoValeCaja.VOIDED?"Anulado":"Confirmado";}
}
